import { config } from '../config/index.js';
import { logger } from '../utils/logger.js';
import { handleAPIError } from './errors.js';

export class APIClient {
  constructor() {
    this.baseURL = config.api.baseURL;
    this.timeout = config.api.timeout;
    this.retries = config.api.retries;
    this.retryDelay = config.api.retryDelay;
  }

  async request(endpoint, data = null, options = {}) {
    const url = `${this.baseURL}${endpoint}`;
    const headers = {
      'Content-Type': 'application/json',
      'Connection': 'keep-alive',
      'Authorization': `Bearer ${config.auth.token}`,
      'X-OAuth-Version': config.auth.oauthVersion,
      ...options.headers
    };

    const requestOptions = {
      method: options.method || 'POST',
      headers,
      timeout: this.timeout,
      ...options
    };

    if (data) {
      requestOptions.body = JSON.stringify(data);
    }

    let lastError;
    
    for (let attempt = 0; attempt <= this.retries; attempt++) {
      try {
        logger.debug(`API request attempt ${attempt + 1}: ${url}`);
        
        const response = await fetch(url, requestOptions);
        
        if (!response.ok) {
          throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }
        
        const result = await response.json();
        logger.debug(`API request successful: ${url}`);
        return result;
        
      } catch (error) {
        lastError = error;
        logger.warn(`API request failed (attempt ${attempt + 1}): ${error.message}`);
        
        if (attempt < this.retries) {
          await this.delay(this.retryDelay * Math.pow(2, attempt)); // 指数退避
        }
      }
    }
    
    logger.error(`API request failed after ${this.retries + 1} attempts: ${lastError.message}`);
    throw handleAPIError(lastError);
  }

  async delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  // 知识库搜索接口（AI处理结果）
  async searchKnowledge(question, topicIds, options = {}) {
    const data = {
      question,
      topic_ids: topicIds,
      deep_seek: options.deep_seek !== undefined ? options.deep_seek : true,
      refs: options.refs || false,
      history: options.history || []
    };

    return this.request('/knowledge/search', data);
  }

  // 知识库召回接口（原始召回结果）
  async recallKnowledge(question, options = {}) {
    const data = {
      question,
      topic_id: options.topic_id,
      topic_ids: options.topic_ids,
      top_k: options.top_k || 10,
      intent_rewrite: options.intent_rewrite || false,
      select_matrix: options.select_matrix || false,
      history: options.history || []
    };

    // 确保至少有一个topic_id参数
    if (!data.topic_id && !data.topic_ids) {
      throw new Error('Either topic_id or topic_ids is required');
    }

    return this.request('/knowledge/search/recall', data);
  }

  // 流式搜索（需要特殊处理）
  async searchKnowledgeStream(question, topicIds, options = {}) {
    const url = `${this.baseURL}/knowledge/search/stream`;
    const headers = {
      'Content-Type': 'application/json',
      'Connection': 'keep-alive',
      'Authorization': `Bearer ${config.auth.token}`,
      'X-OAuth-Version': config.auth.oauthVersion,
      'Accept': 'text/event-stream'
    };

    const data = {
      question,
      topic_ids: topicIds,
      deep_seek: options.deep_seek !== undefined ? options.deep_seek : true,
      refs: options.refs || false,
      history: options.history || []
    };

    const response = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify(data),
      timeout: this.timeout
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    return response.body;
  }
}